contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        // Ensure a clean state first: withdraw anything recorded (succeeds even if zero).
        c.withdrawBalance(); if (__ESBMC_reverted()) return;
        uint beforeSecond = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        // Deposit amount.
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        // Withdraw everything (recorded balance is amount > 0, so it succeeds and zeroes it).
        c.withdrawBalance(); if (__ESBMC_reverted()) return;
        uint afterWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        // Deposit again: recorded balance must be exactly amount, proving no residue survived the withdrawal.
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterRedeposit = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(beforeSecond == 0 && afterWithdraw == 0 && afterRedeposit == amount);
    }
    receive() external payable { }
}

